  static IEnumerator ConsumableClip(LevelManager l,Character p,SyringeDartAbility n){n.enabled=false;n.StopAllCoroutines();l.SetRunFlowPaused(false);Set(l,"timeSinceLastMonsterSpawned",-1000f);var center=(Vector2)p.transform.position;for(int i=0;i<8;i++){var m=Spawn(l,center+new Vector2(2+(i%4)*.35f,(i/4-.5f)*.5f),50);m.enabled=false;}foreach(var key in new[]{"Bomb","Health","Magnet","Red Potion"})AddConsumable(l,p,key);Set(p,"currentHealth",p.MaxHealth*.5f);var bomb=l.PlayerInventory.Slots.First(s=>s.IsBomb);var aim=BombTargeting.For(bomb);bool started=false,thrown=false,healed=false,magnet=false,potion=false;yield return Record("01-use",11,t=>{if(t>.6f&&!started){started=true;aim.BeginAim(bomb);}if(t>.6f&&t<2){Set(aim,"target",center+new Vector2(2.5f,.3f*Mathf.Sin(t*5)));Call(aim,"UpdatePreview");}if(t>2&&!thrown){thrown=true;aim.Confirm(center+Vector2.right*2.5f);}if(t>4&&!healed){healed=true;l.PlayerInventory.Slots.First(s=>s.CollectableType is HealthCollectable).UseItem();}if(t>6&&!magnet){magnet=true;l.PlayerInventory.Slots.First(s=>s.CollectableType is MagnetCollectable).UseItem();}if(t>8&&!potion){potion=true;l.PlayerInventory.Slots.First(s=>s.CollectableType is RedPotionCollectable).UseItem();}if(l.EntityManager.AbilitySelectionDialog.MenuOpen)l.EntityManager.AbilitySelectionDialog.Close();});}
