  static IEnumerator ReversalClip(LevelManager l,Character p,SyringeDartAbility n){n.enabled=false;n.StopAllCoroutines();var center=(Vector2)p.transform.position;var bp=(AttackSpeedDebufferMonsterBlueprint)l.CurrentLevelBlueprint.monsters[16].monsterBlueprints[0];var candy=l.EntityManager.SpawnMonster(16,center+new Vector2(2,1.5f),bp,0);candy.enabled=false;var debuff=p.GetComponent<PlayerAttackSpeedDebuffRuntime>()??p.gameObject.AddComponent<PlayerAttackSpeedDebuffRuntime>();bool applied=false,restored=false;Annotation("입력 →  /  실제 이동 →");yield return Record("01-reversal",bp.debuffDuration+4,t=>{if(t>=1&&!applied){applied=true;debuff.Apply(bp.debuffDuration,new Color(1f,.92156863f,.015686275f),.3f,.8f,.6f,1.5f,5,2.2f,150,false);Annotation("방향 반전 · 같은 입력 → / 이동 ←");}if(applied&&!debuff.IsActive&&!restored){restored=true;Annotation("효과 종료 · 입력 → / 이동 →");}p.Move(t<.8f||t>1.5f&&t<2.5f||t>bp.debuffDuration+1.2f&&t<bp.debuffDuration+2.2f?Vector2.right:Vector2.zero);focus=center+Vector2.right*.6f;});}
  static IEnumerator Record(string name,float duration,Action<float> step){string dir=Out+"/"+name;Directory.CreateDirectory(dir);File.WriteAllText(dir+"/timing.txt","15 fps; "+duration+" game seconds");int frames=Mathf.CeilToInt(duration*15);for(int f=0;f<frames;f++){step?.Invoke(f/15f);yield return null;Frame(name+"/"+f.ToString("D4"));}}
  static void Frame(string name){var camera=Camera.main;if(camera==null)return;var overlays=Object.FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas&&c.renderMode==RenderMode.ScreenSpaceOverlay).ToArray();var cams=overlays.Select(c=>c.worldCamera).ToArray();var distances=overlays.Select(c=>c.planeDistance).ToArray();var orders=overlays.Select(c=>c.sortingOrder).ToArray();var flags=overlays.Select(c=>c.overrideSorting).ToArray();var layers=overlays.Select(c=>c.sortingLayerID).ToArray();var target=camera.targetTexture;var active=RenderTexture.active;var pos=camera.transform.position;float zoom=camera.orthographicSize;var rt=RenderTexture.GetTemporary(960,540,24);Texture2D image=null;try{if(focus.HasValue)camera.transform.position=new Vector3(focus.Value.x,focus.Value.y,pos.z);camera.orthographicSize=size;camera.targetTexture=rt;foreach(var c in overlays){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=camera.nearClipPlane+.1f;c.overrideSorting=true;c.sortingLayerName="Monster Full";c.sortingOrder=Mathf.Clamp(32100+c.sortingOrder,32100,32760);}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=rt;image=new Texture2D(960,540,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,960,540),0,0);image.Apply();File.WriteAllBytes(Out+"/"+name+".png",image.EncodeToPNG());}finally{for(int i=0;i<overlays.Length;i++){overlays[i].renderMode=RenderMode.ScreenSpaceOverlay;overlays[i].worldCamera=cams[i];overlays[i].planeDistance=distances[i];overlays[i].sortingOrder=orders[i];overlays[i].overrideSorting=flags[i];overlays[i].sortingLayerID=layers[i];}camera.targetTexture=target;camera.transform.position=pos;camera.orthographicSize=zoom;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);if(image!=null)Object.Destroy(image);Canvas.ForceUpdateCanvases();}}
 }
